package pool

import (
	"errors"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

// dispatcherGoldenClaude is typed out independently from dispatcherTemplate
// (not by referencing the production constant) — the whole point of a
// golden-file test (§17) is that an accidental edit to dispatcherTemplate
// shows up as a diff against THIS literal, copied verbatim from
// design/harness/unified-harness-pool.md §5.3 with "claude" substituted for
// the name.
const dispatcherGoldenClaude = `#!/bin/sh
# generated by wraptool — do not edit
set -eu
name=claude
root=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)   # .../runtime
m=$(uname -m)
case "$m" in
  x86_64)          arch=amd64 ;;
  aarch64|arm64)   arch=arm64 ;;
  *) echo "wraptool: unsupported architecture $m for $name" >&2; exit 69 ;;
esac
libc=glibc
[ -e "/lib/ld-musl-$m.so.1" ] && libc=musl
key=${WRAPTOOL_PLATFORM:-linux-$arch-$libc}
ptr="$root/active/$key/$name.gen"
if [ ! -f "$ptr" ]; then
  echo "wraptool: $name is not realized for $key;" >&2
  echo "run on the host: wraptool harness sync --platform $key" >&2
  exit 69
fi
gen=$(cat "$ptr")
exec "$root/generations/$gen/bin/$name" "$@"
`

func TestGenerateDispatcherGoldenClaude(t *testing.T) {
	t.Parallel()
	got := string(GenerateDispatcher("claude"))
	if got != dispatcherGoldenClaude {
		t.Errorf("GenerateDispatcher(%q) drifted from the §5.3 golden text.\ngot:\n%s\nwant:\n%s", "claude", got, dispatcherGoldenClaude)
	}
}

// TestGenerateDispatcherContainsNoAbsoluteHostPath pins §6.3: the dispatcher
// must never contain an absolute host path — it works wherever runtime/ is
// mounted. The only "/" prefixed tokens the script contains are the
// $0-relative "/.." resolution and the musl loader probe's fixed container
// path "/lib/ld-musl-...", neither of which name any host filesystem
// location.
func TestGenerateDispatcherContainsNoAbsoluteHostPath(t *testing.T) {
	t.Parallel()
	got := string(GenerateDispatcher("opencode"))
	for _, line := range strings.Split(got, "\n") {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "/") {
			t.Errorf("dispatcher line %q starts with an absolute path", line)
		}
	}
}

// TestGenerateDispatcherUsesLFLineEndings pins §6.3/§6.4's implicit
// requirement that generated bytes are identical on every host: Go string
// literals never contain "\r", so this mostly guards against a future
// template edit introducing one by accident (e.g. copy-pasted from a
// CRLF-saved source).
func TestGenerateDispatcherUsesLFLineEndings(t *testing.T) {
	t.Parallel()
	got := GenerateDispatcher("claude")
	if strings.Contains(string(got), "\r") {
		t.Error("dispatcher contains a CR byte; want LF-only line endings on every host")
	}
}

// --- WriteDispatcher ---

func TestWriteDispatcherWritesExecutableFile(t *testing.T) {
	t.Parallel()
	paths := testPaths(t)
	if err := WriteDispatcher(paths, "claude"); err != nil {
		t.Fatalf("WriteDispatcher: %v", err)
	}
	path := runtimeBinFile(paths.Runtime, "claude")
	info, err := os.Stat(path)
	if err != nil {
		t.Fatalf("stat dispatcher: %v", err)
	}
	if info.Mode().Perm() != 0o755 {
		t.Errorf("dispatcher mode = %o, want 0o755", info.Mode().Perm())
	}
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if string(data) != dispatcherGoldenClaude {
		t.Errorf("written dispatcher content drifted from the golden text; got:\n%s", data)
	}
}

func TestWriteDispatcherRejectsMultiSegmentHarnessName(t *testing.T) {
	t.Parallel()
	paths := testPaths(t)
	if err := WriteDispatcher(paths, "a/b"); err == nil {
		t.Fatal("expected an error for a harness name containing a path separator")
	}
}

// --- behavioral: run the generated script with /bin/sh ---

// dispatcherTestRoot builds a runtime/ tree under t.TempDir() containing the
// dispatcher itself at bin/<harness> — the exact shape a real pool mount
// presents (root/bin/<name>, root/active/<key>/<name>.gen,
// root/generations/<id>/bin/<name>) — and returns its root path. The
// dispatcher resolves "root" as $(dirname "$0")/.., so invoking
// root/bin/<name> directly (its own real path) reproduces $0-relative
// resolution exactly as it happens under a real mount, at any path.
func dispatcherTestRoot(t *testing.T, harnessName string) (root string) {
	t.Helper()
	root = t.TempDir()
	binDir := filepath.Join(root, "bin")
	if err := os.MkdirAll(binDir, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(binDir, harnessName), GenerateDispatcher(harnessName), 0o755); err != nil {
		t.Fatal(err)
	}
	return root
}

// seedDispatcherGeneration creates root/generations/<id>/bin/<name> as a
// tiny real script that echoes its own args (so a test can assert argument
// pass-through) and root/active/<key>/<name>.gen pointing at it.
func seedDispatcherGeneration(t *testing.T, root, key, harnessName, genID string) {
	t.Helper()
	binDir := filepath.Join(root, "generations", genID, "bin")
	if err := os.MkdirAll(binDir, 0o755); err != nil {
		t.Fatal(err)
	}
	script := "#!/bin/sh\necho ran:$0:$@\n"
	if err := os.WriteFile(filepath.Join(binDir, harnessName), []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	activeDir := filepath.Join(root, "active", key)
	if err := os.MkdirAll(activeDir, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(activeDir, harnessName+".gen"), []byte(genID+"\n"), 0o644); err != nil {
		t.Fatal(err)
	}
}

// runDispatcher execs root/bin/<harnessName> with extraEnv OVERRIDING (not
// merely appending to — duplicate-key precedence between env entries is not
// something to rely on) the test process's own environment, so PATH/HOME
// etc. still resolve `uname` and `sh` unless a test deliberately shadows
// PATH itself. Returns combined stdout+stderr and the process error (an
// *exec.ExitError for a non-zero exit, which the caller inspects via
// ExitCode()).
func runDispatcher(t *testing.T, root, harnessName string, extraEnv, args []string) (output string, err error) {
	t.Helper()
	scriptPath := filepath.Join(root, "bin", harnessName)
	//nolint:gosec // test helper, fixed script path under t.TempDir()
	cmd := exec.Command(scriptPath, args...)
	cmd.Env = mergeEnv(os.Environ(), extraEnv)
	out, runErr := cmd.CombinedOutput()
	return string(out), runErr
}

// mergeEnv returns base with every "KEY=VALUE" in overrides replacing base's
// existing entry for that KEY (appended if base has none) — os/exec passes
// its Env slice to the child verbatim, and duplicate-key precedence in a
// process's environment is not something to depend on.
func mergeEnv(base, overrides []string) []string {
	out := make([]string, 0, len(base)+len(overrides))
	overrideKeys := make(map[string]string, len(overrides))
	for _, kv := range overrides {
		if i := strings.IndexByte(kv, '='); i >= 0 {
			overrideKeys[kv[:i]] = kv
		}
	}
	for _, kv := range base {
		i := strings.IndexByte(kv, '=')
		if i < 0 {
			out = append(out, kv)
			continue
		}
		if _, overridden := overrideKeys[kv[:i]]; overridden {
			continue
		}
		out = append(out, kv)
	}
	out = append(out, overrides...)
	return out
}

func TestDispatcherHappyPathExecsAndPassesArgsThrough(t *testing.T) {
	t.Parallel()
	root := dispatcherTestRoot(t, "claude")
	seedDispatcherGeneration(t, root, "linux-amd64-glibc", "claude", "claude-2.1.220-linux-amd64-glibc-deadbeef")

	out, err := runDispatcher(t, root, "claude", []string{"WRAPTOOL_PLATFORM=linux-amd64-glibc"}, []string{"foo", "bar"})
	if err != nil {
		t.Fatalf("dispatcher failed: %v, output:\n%s", err, out)
	}
	if !strings.Contains(out, "ran:") || !strings.Contains(out, "foo bar") {
		t.Errorf("expected the generation script to run with args passed through, got:\n%s", out)
	}
}

func TestDispatcherWraptoolPlatformOverride(t *testing.T) {
	t.Parallel()
	root := dispatcherTestRoot(t, "claude")
	// Seed only an ARM64 generation; without the override the host's own
	// (amd64, in this dev environment) detection would miss it entirely.
	seedDispatcherGeneration(t, root, "linux-arm64-glibc", "claude", "claude-2.1.220-linux-arm64-glibc-deadbeef")

	out, err := runDispatcher(t, root, "claude", []string{"WRAPTOOL_PLATFORM=linux-arm64-glibc"}, nil)
	if err != nil {
		t.Fatalf("dispatcher failed: %v, output:\n%s", err, out)
	}
	if !strings.Contains(out, "ran:") {
		t.Errorf("expected the overridden-platform generation to run, got:\n%s", out)
	}
}

func TestDispatcherMissingPointerExitsUnavailableWithSyncCommand(t *testing.T) {
	t.Parallel()
	root := dispatcherTestRoot(t, "claude")
	// No active/ tree at all: the platform is simply never realized.

	out, err := runDispatcher(t, root, "claude", []string{"WRAPTOOL_PLATFORM=linux-amd64-glibc"}, nil)
	if err == nil {
		t.Fatalf("expected a non-zero exit, got success; output:\n%s", out)
	}
	var exitErr *exec.ExitError
	if !errors.As(err, &exitErr) {
		t.Fatalf("expected an *exec.ExitError, got %T: %v", err, err)
	}
	if exitErr.ExitCode() != 69 {
		t.Errorf("exit code = %d, want 69 (EX_UNAVAILABLE)", exitErr.ExitCode())
	}
	if !strings.Contains(out, "claude is not realized for linux-amd64-glibc") {
		t.Errorf("expected the error to name the harness and platform key, got:\n%s", out)
	}
	if !strings.Contains(out, "wraptool harness sync --platform linux-amd64-glibc") {
		t.Errorf("expected the error to name the exact host fix command, got:\n%s", out)
	}
}

// fakeUnameDir writes an executable `uname` shim into a fresh directory that
// always reports arch, and returns the directory to prepend onto PATH — the
// brief's "unsupported arch via a PATH-shimmed uname" test mechanism.
func fakeUnameDir(t *testing.T, arch string) string {
	t.Helper()
	dir := t.TempDir()
	script := "#!/bin/sh\necho " + arch + "\n"
	if err := os.WriteFile(filepath.Join(dir, "uname"), []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	return dir
}

func TestDispatcherUnsupportedArchExits69(t *testing.T) {
	t.Parallel()
	root := dispatcherTestRoot(t, "claude")
	fakeDir := fakeUnameDir(t, "ppc64")

	out, err := runDispatcher(t, root, "claude", []string{"PATH=" + fakeDir + ":" + os.Getenv("PATH")}, nil)
	if err == nil {
		t.Fatalf("expected a non-zero exit for an unsupported architecture, got success; output:\n%s", out)
	}
	var exitErr *exec.ExitError
	if !errors.As(err, &exitErr) {
		t.Fatalf("expected an *exec.ExitError, got %T: %v", err, err)
	}
	if exitErr.ExitCode() != 69 {
		t.Errorf("exit code = %d, want 69 (EX_UNAVAILABLE)", exitErr.ExitCode())
	}
	if !strings.Contains(out, "unsupported architecture ppc64") {
		t.Errorf("expected the error to name the unsupported architecture, got:\n%s", out)
	}
}
